-- ============================================================================
-- Staging seed — 34 B2B credit notes + the 32 invoices they credit
--
-- accounting_documents ONLY. Nothing here touches shedul; the documents are
-- self-contained for the purpose of exercising the Comarch XML builders.
--
--   houston psql <staging-ns> accounting_documents --write -f staging-seed.sql
--
-- The credit notes carry their ORIGINAL payloads — previous_receipt_number is nil,
-- exactly as production holds them. Deliberate: it leaves
-- update_accounting_document_payload something to do, so the FULL runbook can be
-- rehearsed (patch the payload, then re-drive) rather than only the builder change.
--
-- Each credit note is commented with the reference it SHOULD acquire, from the
-- matcher. The invoices go in first so those references resolve to real documents
-- once the patch is applied.
--
-- To seed the patched payloads instead, take base64_new_payload from
-- decoded-payloads-<ns>-<date>.csv — but then nothing is left to test on the write path.
--
-- ⚠ PASS THE TWO IDS IN. They are production values (both 33) and will not exist in
-- staging. Find yours with:
--   SELECT ac.id AS account_configuration_id, p.id AS plugin_id, ac.country_code
--   FROM account_configurations ac
--   JOIN account_configuration_plugins p ON p.account_configuration_id = ac.id
--   WHERE ac.country_code = 'SA';
--
-- Known: eng-pierogi is 32 / 32 (comarch/zatca, enabled).
--
--   houston psql eng-pierogi accounting_documents --write -- \
--     -v ON_ERROR_STOP=1 \
--     -v account_configuration_id=32 -v account_configuration_plugin_id=32 \
--     -f staging-seed.sql
-- ============================================================================

-- `\set` would clobber a -v, so each is defaulted only when not already set.
\if :{?account_configuration_id}
\else
  \set account_configuration_id 0
\endif
\if :{?account_configuration_plugin_id}
\else
  \set account_configuration_plugin_id 0
\endif

-- psql's \if takes a boolean literal only — it cannot evaluate `0 = 0` — so the
-- comparison is done by the server and read back with \gset.
SELECT (:account_configuration_id = 0 OR :account_configuration_plugin_id = 0) AS ids_unset \gset
\if :ids_unset
  \echo '!! Pass -v account_configuration_id=<id> -v account_configuration_plugin_id=<id>'
  \quit
\endif

-- And check the pair exists and belongs together, before inserting 66 rows against a
-- foreign key that would fail anyway — with a message naming which id is wrong.
SELECT NOT EXISTS (
  SELECT 1
  FROM account_configuration_plugins p
  JOIN account_configurations ac ON ac.id = p.account_configuration_id
  WHERE p.id = :account_configuration_plugin_id
    AND ac.id = :account_configuration_id
) AS ids_bad \gset
\if :ids_bad
  \echo '!! No account_configuration_plugin with that id belongs to that account_configuration.'
  \quit
\endif

BEGIN;

-- Ids come from the sequence rather than being hardcoded, so this cannot collide
-- with anything already in the target database. Rows are correlated afterwards by
-- einvoice_reference, which carries a partial unique index (WHERE NOT NULL).

