-- ---------------------------------------------------------------------------
-- 3. Trackers. Invoices land approved/sent; credit notes land rejected/rejected,
--    which is what makes them RETRY-ELIGIBLE — the retry action filters on
--    `upload_status = 'failed_to_send' OR review_status = 'rejected'`, and
--    FORCE=true does NOT bypass that filter. Seeding any other pair means the
--    task silently drops them and still reports success.
-- ---------------------------------------------------------------------------
INSERT INTO e_invoice_trackers (accounting_document_id, review_status, upload_status, created_at, updated_at)
SELECT ad.id, 'approved', 'sent', ad.created_at, now()
FROM accounting_documents ad
WHERE ad.einvoice_reference IN (
    '671f9f59-1a00-4c93-94fe-f76c2e0f51a0',
