-- ---------------------------------------------------------------------------
-- 4. Point each document at its tracker. Separate statement because the FKs are
--    mutual: accounting_documents.latest_tracker_id -> e_invoice_trackers.id and
--    e_invoice_trackers.accounting_document_id -> accounting_documents.id, so
--    neither row can name the other at insert time.
-- ---------------------------------------------------------------------------
UPDATE accounting_documents ad
SET latest_tracker_id = t.id, updated_at = now()
FROM e_invoice_trackers t
WHERE t.accounting_document_id = ad.id
  AND ad.latest_tracker_id IS NULL;

-- ---------------------------------------------------------------------------
-- 5. Read it back before committing.
-- ---------------------------------------------------------------------------
SELECT ad.document_type, t.review_status, t.upload_status, count(*)
FROM accounting_documents ad
JOIN e_invoice_trackers t ON t.id = ad.latest_tracker_id
